using System;using System.Data;using System.Data.SqlClient;using HRM.DAL;namespace HRM.BUS{public class HRMBUS{HRMDAL d=new HRMDAL();public DataTable Get(string t){if(t=="NhanVien")return d.Query("SELECT n.MaNV,n.HoTen,n.NgaySinh,n.CCCD,n.MaPB,p.TenPB,n.LuongCoBan,n.HeSoLuong FROM NhanVien n JOIN PhongBan p ON n.MaPB=p.MaPB");if(t=="PhongBan")return d.Query("SELECT * FROM PhongBan");throw new Exception("Bảng không hợp lệ");}public DataTable Search(string s){return d.Query("SELECT n.MaNV,n.HoTen,n.NgaySinh,n.CCCD,n.MaPB,p.TenPB,n.LuongCoBan,n.HeSoLuong FROM NhanVien n JOIN PhongBan p ON n.MaPB=p.MaPB WHERE n.HoTen LIKE @k OR n.CCCD LIKE @k OR p.TenPB LIKE @k",new SqlParameter("@k","%"+s+"%"));}public DataTable Departments(){return d.Query("SELECT MaPB,TenPB FROM PhongBan");}public void AddDept(string name,string desc){d.Exec("INSERT PhongBan(TenPB,Mota) VALUES(@n,@d)",new SqlParameter("@n",name),new SqlParameter("@d",(object)desc??DBNull.Value));}public void AddEmp(string name,object dob,string cccd,int pb,decimal salary,double factor){d.Exec("INSERT NhanVien(HoTen,NgaySinh,CCCD,MaPB,LuongCoBan,HeSoLuong) VALUES(@n,@dob,@cc,@pb,@s,@h)",new SqlParameter("@n",name),new SqlParameter("@dob",dob??DBNull.Value),new SqlParameter("@cc",cccd),new SqlParameter("@pb",pb),new SqlParameter("@s",salary),new SqlParameter("@h",factor));}public void UpdateEmp(int id,string name,object dob,string cccd,int pb,decimal salary,double factor){d.Exec("UPDATE NhanVien SET HoTen=@n,NgaySinh=@dob,CCCD=@cc,MaPB=@pb,LuongCoBan=@s,HeSoLuong=@h WHERE MaNV=@id",new SqlParameter("@n",name),new SqlParameter("@dob",dob??DBNull.Value),new SqlParameter("@cc",cccd),new SqlParameter("@pb",pb),new SqlParameter("@s",salary),new SqlParameter("@h",factor),new SqlParameter("@id",id));}public void DeleteEmp(int id){d.Exec("DELETE NhanVien WHERE MaNV=@id",new SqlParameter("@id",id));}public void DeleteDept(int id){d.Exec("DELETE PhongBan WHERE MaPB=@id",new SqlParameter("@id",id));}public DataTable Attendance(string m){return d.GetAttendance(m);}public void SaveAttendance(DataTable t){d.SaveAttendance(t);}public void Payroll(string m){d.ClosePayroll(m);}public DataTable Salaries(string m){return d.Query("SELECT l.MaNV,n.HoTen,l.ThangNam,l.ThucLinh FROM BangLuong l JOIN NhanVien n ON l.MaNV=n.MaNV WHERE l.ThangNam=@m ORDER BY n.HoTen",new SqlParameter("@m",m));}}}